// Atlas places: the text shown when you click a city or a region on the map.
// Keys: 'city:<name>' for each city (or archaeological site) in KEYFRAMES[*].cities (history.js)
// and ERAS[*].cities (eras.js); 'reg:<name>' for each region/people in KEYFRAMES[*].regions.
// The name after the prefix is exactly the one on the map. When the same place appears under different names
// (Vila Rica / Ouro Preto, Desterro / Florianópolis, Edo / Tokyo...), each name has its own entry.
// txt: 2 or 3 simple sentences. What the place or people is, when it flourished, who lived there and which
// other places it was linked to. Archaeological dates are approximate; where there is debate, the text says so.
// ev: ids of events from EVENTS (history.js + world.js) linked to the place, at most 4.

export const LOCATIONS = {
  // ---------- First inhabitants and archaeological sites ----------
  'city:Monte Verde': { txt: "A camp beside a stream in southern Chile, occupied some 14,500 years ago, where peat preserved wood, hide, plants and even food scraps. It was the site that convinced most archaeologists that people were in the Americas before the Clovis culture of North America. It shows that the first groups arrived very early and very far south, probably following the Pacific coast." },
  'city:Pedra Furada (Serra da Capivara)': { txt: "A rock shelter in southeastern Piauí, at the heart of Serra da Capivara National Park, with thousands of rock paintings. Niède Guidon’s team proposed occupations more than 30,000 years old, but many archaeologists think the oldest chipped stones and hearths may be natural. A human presence around 12,000 years ago is accepted. The site is at the center of a still-open debate about when people reached South America.", ev: ['luzia'] },
  'city:Santa Catarina sambaquis': { txt: "Sambaquis are artificial mounds of shells, bones and earth. These are on the coast of Santa Catarina, mainly around Laguna, and some are more than 30 meters high. They were built by fishing and foraging peoples between about 7,000 and 1,000 years ago and also served as cemeteries and landmarks. They prove that people without farming could live in one place, in large numbers, for thousands of years.", ev: ['sambaquis'] },
  'city:Guanabara sambaquis': { txt: "Sambaquis (shell mounds) around Guanabara Bay and the nearby lagoons, such as the one at Camboinhas, in Niterói, one of the oldest on the coast, about 8,000 years old. Many were destroyed to make lime in colonial times. They belong to the same tradition of fishers and foragers that occupied the coast from Espírito Santo to Santa Catarina.", ev: ['sambaquis'] },
  'city:Cananeia sambaquis': { txt: "A group of dozens of sambaquis (shell mounds) in the Cananeia and Iguape estuary system, in southern São Paulo, occupied for thousands of years. Mangroves rich in fish and shellfish allowed stable villages without gardens. The oldest dates in the region are debated, but they are around 6,000 to 8,000 years.", ev: ['sambaquis'] },
  'city:Taperinha': { txt: "A river shell mound near Santarém, on the lower Amazon, made of freshwater mollusk shells. Anna Roosevelt dated pottery there to some 7,000 to 8,000 years ago, among the oldest in the Americas, made by fishers and foragers long before intensive farming. It shows that the Amazon was not a backwater: it was one of the places where pottery appeared early.", ev: ['pedrapintada'] },
  'city:Teotônio (upper Madeira)': { txt: "A site beside a former waterfall on the Madeira River, near Porto Velho, occupied almost continuously for about 9,000 years. It has layers of dark earth (terra preta), varied pottery and signs of early cultivation. Southwestern Amazonia is seen as the cradle of manioc and perhaps of the Tupi languages. The waterfall was flooded by the Santo Antônio dam in the 2010s.", ev: ['tupiguarani', 'terrapreta'] },
  'city:Marajó mounds': { txt: "The tesos are artificial mounds built on Marajó Island by the Marajoara culture, roughly between 400 and 1400 AD, to stay above the floods. They held houses, cemeteries with painted urns, and fish management in lakes and canals. Archaeologists debate whether these were ranked societies or related groups who cooperated without a supreme chief.", ev: ['marajoara'] },
  'city:Acre geoglyphs': { txt: "Hundreds of ditches shaped like circles and squares in eastern Acre, revealed by deforestation and built mostly between about 2,000 and 700 years ago. They have almost no remains of houses: they seem to have been places of gathering and ceremony, made in a forest that was managed, not cleared. They show Amazonian peoples able to carry out large collective works without a city or a state.", ev: ['geoglyphs'] },
  'city:Açutuba': { txt: "A large archaeological site on the lower Rio Negro, near Manaus, studied by Eduardo Neves’s Central Amazon Project. It was occupied for centuries, roughly between 300 BC and 1400 AD, and has dark earth, mounds and ditches. It is one of the examples of large, long-lasting villages in the central Amazon, linked by rivers to other peoples.", ev: ['terrapreta'] },
  'city:Tiwanaku': { txt: "A ceremonial center and city near Lake Titicaca, in present-day Bolivia, which flourished roughly between 500 and 1000 AD. Its raised fields fed many people, and llama caravans carried its influence as far as northern Chile. No one knows for sure whether it was an empire, a confederation or a religious center that drew pilgrims." },
  'city:Huari': { txt: "Capital of the Wari culture, near present-day Ayacucho, in the Andes of Peru, which flourished from about 600 to 1000 AD. The Wari built administrative centers and roads that the Incas later reused. Many call Wari the first Andean empire; others think it was a looser network of alliances.", ev: ['inca'] },
  'city:Huacas de Moche': { txt: "Two large adobe pyramids, the Huaca del Sol and the Huaca de la Luna, near Trujillo, on the north coast of Peru. They were the center of the Moche culture, which flourished roughly from 100 to 800 AD with irrigation in the desert and pottery that portrays people, rituals and sacrifices. The region was later taken over by the Chimú of Chan Chan." },
  'city:Tikal': { txt: "A large Maya city in the Petén forest, in Guatemala, with pyramid temples and thousands of scattered houses. It peaked between about 200 and 850 AD. It rivaled Calakmul for centuries and, in 378, received a group from Teotihuacan that changed its dynasty. It was abandoned in the collapse of the southern Maya cities, in the 9th century.", ev: ['maya', 'teotihuacan'] },
  'city:Chan Chan': { txt: "Capital of the Chimú kingdom, in the Moche valley, on the north coast of Peru, built in adobe from about 900 AD. It had large walled compounds for the elite and quarters for craftsmen. The Incas conquered it around 1470 and took its goldsmiths to Cusco.", ev: ['inca'] },
  'city:Santarém (Tapajó)': { txt: "At the mouth of the Tapajós, between about 1000 and 1600 AD, lived a people of large villages known for elaborate pottery covered with figures. Friar Carvajal, of Orellana’s expedition (1542), described many people there and feared warriors. The Jesuits set up a mission in 1661, the origin of the town of Santarém.", ev: ['tapajo'] },
  'city:Xingu villages': { txt: "In the upper Xingu, ancestors of the Kuikuro lived from about 1250 to 1600 in large villages linked by straight roads, ditches and bridges. Michael Heckenberger called this garden urbanism: many people and much planning, without a state. There, peoples of different languages formed a regional system of exchange and festivals that still exists today.", ev: ['xingu'] },
  'city:Tupinambá villages': { txt: "Villages of Tupi-speaking peoples who, by around the year 1000, were already spreading along the coast, pushing out or absorbing older groups. They had longhouses where several families lived, manioc gardens and ritual wars between villages. These were the peoples the Europeans met on the coast in 1500.", ev: ['tupi', 'tupiguarani'] },
  'city:Guarani villages of the Paraná': { txt: "Guarani villages in the forests along the Paraná, Paraguay and Uruguay rivers, with gardens of maize and manioc and painted pottery. The Guarani are close relatives of the coastal Tupi and spoke a very similar language. Through mobility and alliances, they occupied an enormous territory without forming a state.", ev: ['tupiguarani'] },
  'city:Cahokia': { txt: "The largest city in America north of Mexico, near present-day St. Louis, in the Mississippi valley, at its peak between 1050 and 1200. It had perhaps 10,000 to 20,000 inhabitants, a debated figure, and Monks Mound, an earthwork 30 meters high. It was abandoned around 1350, and some think the peoples of the region deliberately rejected this model of concentrated power.", ev: ['cahokia'] },
  'city:Chichén Itzá': { txt: "A Maya city in northern Yucatán that became the largest center in the region roughly between 800 and 1100, beside a sacred cenote. It has huge pyramids and a huge ballcourt, in styles that recall the Toltecs of central Mexico; the nature of that link is debated. It traded by sea and by land, receiving even turquoise from what is now the southwestern United States.", ev: ['maya'] },

  // ---------- European expansion, the Atlantic and the Indian Ocean ----------
  'city:Lisbon': { txt: "Capital of Portugal and the port from which fleets left for Africa, India and Brazil from the 15th century on. Between 1580 and 1640 it was under the king of Spain. In 1755 it was destroyed by an earthquake and rebuilt by Pombal. In 1807 the court fled from there to Rio ahead of the French invasion, reversing for some years the relation between mother country and colony.", ev: ['iberianunion', 'restoration', 'pombal', 'junot'] },
  'city:Seville': { txt: "A city in southern Spain, on the Guadalquivir River, which from 1503, through the House of Trade (Casa de Contratación), held the monopoly of trade with the Americas. The silver of Potosí and Mexico arrived there and went on to pay for wars and debts all over Europe. In 1717 the monopoly passed to Cádiz.", ev: ['columbus1492', 'potosi', 'iberianunion'] },
  'city:Mbanza Kongo': { txt: "Capital of the Kingdom of Kongo, in the north of present-day Angola, a state already organized when the Portuguese arrived in 1483. King Afonso I adopted Christianity and, in 1526, wrote to the king of Portugal complaining about the trade in people. The city was renamed São Salvador and stayed linked to Brazil through the slave trade.", ev: ['kongo', 'slavetrade'] },
  'city:Cusco': { txt: "Capital of the Inca Empire, in the Andes of southern Peru, which grew mainly from the time of Pachacuti, around 1438. From there ran roads that linked a territory stretching from Ecuador to Chile. Pizarro’s Spaniards took it in 1533 and built churches on top of the Inca walls.", ev: ['inca', 'pizarro', 'tupacamaru'] },
  'city:Tenochtitlan': { txt: "A Mexica city founded around 1325 on an island in Lake Texcoco, linked to land by causeways and surrounded by chinampas, garden beds built on the water. In the early 16th century it was perhaps one of the largest cities in the world, with one or two hundred thousand inhabitants, figures that are debated. It fell in 1521 to the Spaniards and to many Indigenous allies, such as Tlaxcala.", ev: ['tenochtitlan', 'cortes', 'tlaxcala'] },
  'city:Calicut': { txt: "A port on the Malabar Coast, in southwestern India, ruled by the zamorin and the center of the pepper trade in the Indian Ocean. Arab, Gujarati and Chinese merchants already came to the city; the fleets of Zheng He passed through in the early 15th century. Vasco da Gama arrived in 1498, opening the Portuguese route around the Cape of Good Hope.", ev: ['gama', 'zhenghe'] },
  'city:Tupinambá villages of the Bay of All Saints': { txt: "Tupinambá villages around the Bay of All Saints, with thousands of people, manioc gardens and networks of alliance and war. They received, and later fought, the Portuguese when Salvador was founded in 1549. The smallpox epidemics of the 1560s and the wars reduced them drastically.", ev: ['tupi', 'salvador', 'epidemics'] },
  'city:Tupinambá villages of Guanabara': { txt: "Villages of the Tupinambá, called Tamoios, around Guanabara Bay and along the coast as far as Ubatuba. They allied with the French of France Antarctique (1555) and fought the Portuguese and their Tupiniquim allies in the Tamoio Confederation. Hans Staden, once their prisoner, and Jean de Léry left the most detailed accounts of these peoples.", ev: ['tamoios', 'franceantarctique', 'tupi'] },
  'city:Upper Xingu villages': { txt: "Villages of the peoples of the upper Xingu, speakers of Carib, Arawak and Tupi languages, bound together by marriages, exchange and festivals such as the Kuarup. Before the European arrival they were very populous; epidemics reached them before the colonizers themselves. They stayed out of colonial reach for centuries, protected by distance.", ev: ['xingu', 'xingu1961'] },
  'city:Potiguara villages': { txt: "Villages of the Potiguara, a Tupi people of the coast of Paraíba and Rio Grande do Norte. They allied with French brazilwood traders and resisted the Portuguese until the end of the 16th century. Later, some of them fought alongside the Dutch and some against them. The Potiguara still live today on the Baía da Traição, in Paraíba.", ev: ['tupi', 'brazilwood'] },
  'city:Guarani villages': { txt: "Guarani villages in the forests of the Plata basin, from the coast of Santa Catarina to Paraguay. The Spaniards of Asunción made alliances with them through marriage. The Jesuits gathered them into missions from 1609, and the bandeirantes (slave-raiding expeditions) from São Paulo hunted them as slaves. Even so, the Guarani are still present throughout the region.", ev: ['missions', 'bandeiras'] },
  'city:Tupiniquim villages': { txt: "Tupiniquim villages in southern Bahia and São Vicente. It was Tupiniquim people who met Cabral’s fleet at Porto Seguro in 1500 and who traded brazilwood for tools with the first Portuguese. In São Vicente, the chief Tibiriçá allied with the settlers, in a game of alliances against the Tamoios.", ev: ['cabral', 'brazilwood', 'captaincies'] },
  'city:Salvador': { txt: "Founded in 1549 by Tomé de Sousa as the seat of the general government, it was the capital of Brazil until 1763. It was the sugar port of the Recôncavo and one of the largest destinations for enslaved Africans, linked directly to the Mina Coast and to Angola. The Bahian Conspiracy of 1798 and the Malê Revolt of 1835 took place there.", ev: ['salvador', 'openports', 'bahia1798', 'males'] },
  'city:Olinda': { txt: "A town founded around 1535 by Duarte Coelho, lord-proprietor of Pernambuco, the richest sugar captaincy in the 16th century. The Dutch burned it in 1631 and made neighboring Recife their capital. Later, the rivalry between the nobility of Olinda and the merchants of Recife led to the War of the Peddlers (1710-1711).", ev: ['sugar', 'dutch', 'captaincies'] },
  'city:São Vicente': { txt: "The first Portuguese town in Brazil, founded in 1532 by Martim Afonso de Sousa on the coast of São Paulo. It lived on its alliance with the Tupiniquim and on small sugar mills. From there settlers climbed the coastal range to the Piratininga plateau, where São Paulo would be born.", ev: ['captaincies', 'tamoios'] },
  'city:Goa': { txt: "A city on the west coast of India, conquered by Afonso de Albuquerque in 1510 and made the capital of the Portuguese State of India. It was a hub of the routes linking Lisbon, Mozambique, Hormuz, Malacca and Macau. It had an Inquisition tribunal from 1560 and remained under Portugal until 1961.", ev: ['gama'] },
  'city:Mexico City': { txt: "Built by the Spaniards on the ruins of Tenochtitlan after 1521, it was the capital of the Viceroyalty of New Spain. It was linked to Manila by the galleon that sailed from Acapulco, and Mexican silver traveled as far as China. Capital of independent Mexico since 1821, it was the stage of revolutions and grew into one of the largest cities in the world.", ev: ['cortes', 'manila', 'hidalgo', 'mexico1910'] },
  'city:Lima': { txt: "Founded by Francisco Pizarro in 1535 on the coast of Peru, it was the capital of the Viceroyalty of Peru, which for a long time included almost all of Spanish South America. The silver of Potosí passed through the nearby port of Callao. It was one of the last royalist strongholds, independent in 1821 and secured by the campaign of Bolívar and Sucre.", ev: ['pizarro', 'potosi', 'bolivar'] },
  'city:Madrid': { txt: "Capital of Spain since 1561, by decision of Philip II. Between 1580 and 1640 it also governed Portugal and its empire, including Brazil. The Treaty of Madrid (1750), which drew much of Brazil’s present borders, was signed there.", ev: ['madrid', 'iberianunion', 'spain1808'] },
  'city:Amsterdam': { txt: "A Dutch port that in the 17th century became the financial center of Europe, home of the East India Company (1602) and of the chambers of the West India Company (1621). It refined sugar from Brazil and financed the occupation of Pernambuco. It sheltered Jews of Portuguese origin, some of whom lived in Dutch Recife.", ev: ['vocamsterdam', 'dutch', 'caribbean'] },
  'city:Rio de Janeiro': { txt: "Founded in 1565 by Estácio de Sá, after the French were expelled and with the support of Araribóia’s Temiminó. It grew as the port for gold and for the slave trade with Angola, became capital of the colony in 1763 and seat of the Portuguese court in 1808. It was capital of the Empire and of the Republic until 1960.", ev: ['franceantarctique', 'riocapital', 'court', 'abolition'] },
  'city:São Paulo': { txt: "It was born in 1554 from a Jesuit college on the Piratininga plateau, in a land of alliances between settlers and Tupiniquim. For a long time it was a poor town, the starting point of the bandeiras, expeditions that captured Indigenous people and searched for gold. With coffee, railways and immigrants, it became in the 20th century the country’s largest city and industrial center.", ev: ['bandeiras', 'independence', 'artweek22', 'diretas'] },
  'city:Luanda': { txt: "Founded in 1576 by Paulo Dias de Novais, for three centuries it was the largest port of embarkation for enslaved Africans bound for Brazil. The Dutch occupied it from 1641 to 1648, and a fleet from Rio de Janeiro retook it. The ties with Brazil were so strong that, at Brazil’s independence, some people in Luanda wanted to join Brazil.", ev: ['luanda', 'luanda1641', 'slavetrade'] },
  'city:Recife': { txt: "It began as the port of Olinda and became the capital of Dutch Brazil (1630-1654), when John Maurice of Nassau built Mauritsstad there. It had the first synagogue in the Americas, Kahal Zur Israel. In the 19th century it was the center of the Pernambuco Revolution of 1817 and the Confederation of the Equator of 1824.", ev: ['dutch', 'pernambuco1817', 'equatorconfederation'] },
  'city:Palmares': { txt: "A group of mocambos (runaway settlements) in the Serra da Barriga, in present-day Alagoas, formed by people who had fled the sugar mills since the late 16th century. It came to hold thousands of inhabitants, with gardens, trade with neighbors and leaders such as Ganga Zumba and Zumbi. It resisted dozens of expeditions until it was destroyed in 1694-1695.", ev: ['palmares'] },
  'city:Guarani missions': { txt: "Settlements organized by Jesuits with the Guarani from 1609, first in Guairá and later between the Paraná and Uruguay rivers. They had stone churches, workshops and armed militias, and life combined Jesuit rules with Guarani leadership. The bandeirante attacks of 1628-1631 destroyed those in Guairá; the rest lasted until the expulsion of the Jesuits in 1767-1768.", ev: ['missions', 'bandeiras', 'guaraniwar'] },
  'city:London': { txt: "Capital of England and, from the 18th century, of the largest maritime empire and the largest financial market in the world. Through the Methuen Treaty (1703) and the treaties of 1810, it was closely tied to Portugal and Brazil, and much of the gold of Minas went there. After banning the slave trade in 1807, it pressed Brazil to do the same.", ev: ['methuen', 'treaties1810', 'abolition1807', 'aberdeen'] },
  'city:Belém': { txt: "Founded in 1616 with the Forte do Presépio, at the mouth of the Amazon, as a base to drive the Dutch, English and French out of the region. It was capital of the State of Grão-Pará, which answered directly to Lisbon, and the port for the drogas do sertão, the spices and other products of the forest. It was the center of the Cabanagem revolt (1835-1840) and grew rich again with rubber.", ev: ['cabanagem', 'rubber'] },
  'city:São Luís': { txt: "Founded by the French in 1612 and taken by the Portuguese in 1615; the Dutch occupied it from 1641 to 1644. It was capital of the State of Maranhão, separate from Brazil, and in the 18th century it exported cotton and rice grown by enslaved Africans. Its center of tiled mansions dates from that period.", ev: ['dutch'] },
  'city:Bridgetown': { txt: "Capital of the island of Barbados, an English colony since 1627. In the 1640s the island switched from tobacco to sugar, using techniques and credit brought by Dutch and Jewish people who had been in Brazil. It became the model of the slave plantation society of the English Caribbean and a direct competitor of Brazilian sugar.", ev: ['caribbean'] },
  'city:Paris': { txt: "Capital of France and one of the intellectual centers of Europe since the Middle Ages. The Revolution of 1789 and Napoleon’s wars, launched from there, caused the Portuguese court to flee to Rio and set off the independence of the Americas. The revolutions of 1848 began there and spread across Europe.", ev: ['france1789', 'napoleon', 'spring1848'] },
  'city:Vila Rica': { txt: "A mining camp born of the gold rush in the 1690s and made a town in 1711, it was the capital of the captaincy of Minas Gerais. Miners, enslaved Africans, merchants and artists such as Aleijadinho gathered there. It was the center of the Minas Conspiracy (Inconfidência Mineira) of 1789 and was renamed Ouro Preto in 1823.", ev: ['gold', 'minasconspiracy'] },
  'city:Colônia do Sacramento': { txt: "Founded by the Portuguese in 1680 on the north bank of the Río de la Plata, right across from Buenos Aires, to smuggle silver. It changed hands several times between Portugal and Spain. The Treaty of Madrid (1750) traded it for the Sete Povos das Missões, but the exchange failed, and it became Spanish in 1777.", ev: ['madrid'] },
  'city:Buenos Aires': { txt: "Founded for good in 1580, after a failed attempt in 1536, it was for a long time a minor port that lived on smuggling with the Portuguese and the English. In 1776 it became capital of the Viceroyalty of the Río de la Plata, and in 1810 the May Revolution began Argentine independence. It fought Brazil for control of the Banda Oriental.", ev: ['buenosaires', 'cisplatina', 'madrid'] },
  'city:Sete Povos das Missões': { txt: "Seven Jesuit-Guarani missions east of the Uruguay River, in present-day Rio Grande do Sul, founded or refounded from 1682, such as São Miguel. The Treaty of Madrid ordered them handed to Portugal and their inhabitants moved. The Guarani refused and fought in the Guarani War (1754-1756), in which Sepé Tiaraju died. Today ruins remain, and São Miguel is a World Heritage Site.", ev: ['madrid', 'guaraniwar', 'missions'] },
  'city:Diamantina': { txt: "The former Arraial do Tijuco, in northern Minas, where diamonds were found in the 1720s. The Crown created the Diamond District there, isolated and closely controlled, with mining by enslaved people under a royal monopoly. It is also known for the story of Chica da Silva, a freed woman who lived with the diamond contractor João Fernandes.", ev: ['gold'] },
  'city:Cap-Français': { txt: "The main port of Saint-Domingue, the French colony that in the 18th century was the world’s largest producer of sugar and coffee, at the cost of hundreds of thousands of enslaved people. It was burned in 1793, during the Haitian Revolution. Today it is called Cap-Haïtien.", ev: ['haiti', 'caribbean'] },
  'city:Manchester': { txt: "A city in northwestern England that became the symbol of the Industrial Revolution, with cotton mills driven by water and later by steam. The cotton came from plantation lands, at first partly from Brazil and later mainly from the southern United States. Its cheap cloth flooded markets from India to South America.", ev: ['industrialrev'] },
  'city:Port-au-Prince': { txt: "Capital of Saint-Domingue from 1770 and of Haiti after independence in 1804, won by the largest slave revolt in history. The Haitian example frightened slaveholders in Brazil and throughout the Americas. Haiti was forced to pay France a huge indemnity, which weighed on its economy for more than a century.", ev: ['haiti'] },
  'city:Liverpool': { txt: "A port in northwestern England that in the 18th century was Britain’s largest slave-trading port. After the slave trade was banned in 1807, it lived on importing cotton for the mills of Manchester and on the steamship lines that linked England to South America, including Brazil.", ev: ['slavetrade', 'abolition1807', 'industrialrev'] },
  'city:New York': { txt: "Founded by the Dutch as New Amsterdam in 1624-1626 and taken by the English in 1664, in the 19th century it became the main port of the United States and the gateway for millions of immigrants. It was the financial center where, among other things, Brazilian coffee was traded. The stock market crash of 1929 brought down the price of coffee and helped bring down Brazil’s Old Republic.", ev: ['crash29'] },
  'city:Santiago': { txt: "Founded in 1541 by Pedro de Valdivia in the central valley of Chile, on a frontier of constant war with the Mapuche. Capital of independent Chile since 1818. In 1973 it was the stage of the coup that overthrew Salvador Allende, one of the landmarks of the South American dictatorships.", ev: ['chile1973'] },
  'city:Bogotá': { txt: "Founded in 1538 by Gonzalo Jiménez de Quesada near Bacatá, a Muisca center. It was capital of the Viceroyalty of New Granada and later of Bolívar’s Gran Colombia. Today it is the capital of Colombia.", ev: ['bolivar'] },
  'city:Asunción': { txt: "Founded in 1537 on the Paraguay River, it was the base of the Spanish presence in the interior of the Plata region, built on kinship alliances with the Guarani. Independent Paraguay (1811) was ruled for a long time by Francia and by the López family. In the Paraguayan War, Brazilian troops occupied the city in 1869.", ev: ['paraguaywar'] },
  'city:Montevideo': { txt: "Founded by the Spaniards around 1724-1726 to hold back the Portuguese of Colônia do Sacramento. It was occupied by Brazil as capital of the Cisplatina province until the Cisplatine War, which ended with the independence of Uruguay in 1828. It played an important role in the Plata wars that led to the Paraguayan War.", ev: ['cisplatina', 'paraguaywar'] },
  'city:Manaus': { txt: "It began as the fort of Barra do Rio Negro, from 1669, in the territory of peoples such as the Manao, who gave the city its name. With rubber, between 1879 and 1912, it gained electric light, streetcars and the Teatro Amazonas, paid for by the labor of indebted rubber tappers. When Asian rubber brought prices down, the city entered a long crisis that lasted until the Free Trade Zone of 1967.", ev: ['rubber'] },
  'city:Fortaleza': { txt: "It began with a Dutch fort in 1649, retaken by the Portuguese, and became a town in 1726. In the 19th century it exported cotton, and in 1884 Ceará abolished slavery, four years before the rest of the country. The great droughts, such as that of 1877-1879, pushed thousands of people from Ceará to the rubber estates of the Amazon.", ev: ['rubber', 'abolition'] },
  'city:Santos': { txt: "A town founded by Brás Cubas around 1546, on the coast of São Paulo. With the São Paulo Railway (1867), it became the largest coffee port in the world and the gateway for immigrants. In 1908 the Kasato Maru arrived there, with the first Japanese immigrants.", ev: ['coffee', 'immigration', 'kasato'] },
  'city:Porto Alegre': { txt: "Founded in the 18th century by couples from the Azores on the shores of Lake Guaíba, it became the capital of Rio Grande do Sul. It stayed in the Empire’s hands during almost all of the Ragamuffin War (Farrapos, 1835-1845). In 1930, the armed movement that brought Getúlio Vargas to power set out from there.", ev: ['farroupilha', 'rev1930'] },
  'city:Desterro': { txt: "The town of Nossa Senhora do Desterro, on Santa Catarina Island, founded in the 17th century and settled by Azoreans from 1748. It was a military outpost of the Crown on the way to the Plata. In 1894 it was renamed Florianópolis, in honor of Floriano Peixoto, after the crushing of the Federalist Revolution." },
  'city:Cuiabá': { txt: "It was born from the discovery of gold in 1719 by bandeirantes from São Paulo, who reached it by the monções, long canoe journeys along the rivers. The Payaguá and Guaikuru attacked these convoys. Capital of Mato Grosso from 1835, it stayed isolated until the 20th century, and that is why it was the base of the Rondon Commission.", ev: ['gold', 'paraguaywar', 'rondon'] },
  'city:Goiás': { txt: "The former Vila Boa de Goiás, founded after Bartolomeu Bueno da Silva, son of the Anhanguera, found gold in the region in the 1720s. It was the capital of Goiás until the move to Goiânia in 1937. It preserves its colonial houses and is a World Heritage Site.", ev: ['gold'] },
  'city:Ouro Preto': { txt: "The new name of Vila Rica from 1823, when it was already capital of the province of Minas Gerais. The gold had run out, but the town remained a political center, with the School of Mines founded in 1876. It lost its place as capital to Belo Horizonte in 1897.", ev: ['minasconspiracy', 'gold'] },
  'city:Caracas': { txt: "Founded in 1567 in a valley near the coast of Venezuela, it grew on cacao exported to Spain and Mexico. Birthplace of Simón Bolívar, it was one of the first centers of Spanish American independence, in 1810-1811. Today it is the capital of Venezuela.", ev: ['bolivar'] },
  'city:New Orleans': { txt: "Founded by the French in 1718 near the mouth of the Mississippi, it passed to Spain and, in 1803, to the United States. In the 19th century it was the great cotton port and the largest slave market in the country. It was taken by the Union in 1862, during the Civil War.", ev: ['civilwar'] },
  'city:Hamburg': { txt: "A port city in northern Germany, a former member of the Hanseatic League. In the 19th century it was a major buyer of Brazilian coffee and the port of departure for German emigrants to southern Brazil, such as those who founded Joinville in 1851. Hamburg merchants kept trading houses in Brazilian ports.", ev: ['immigration'] },
  'city:Edo': { txt: "Seat of the Tokugawa shogunate in Japan from 1603 and, in the 18th century, perhaps the largest city in the world, with about a million inhabitants. Japan tightly controlled contact with foreigners until American ships arrived in 1853. In 1868, with the Meiji Restoration, it became the imperial capital under the name Tokyo.", ev: ['meiji'] },
  'city:Vassouras': { txt: "A town in the Paraíba valley of Rio de Janeiro that in the mid-19th century was one of the largest coffee centers, in the hands of barons and tens of thousands of enslaved Africans. In 1838 it saw the revolt of Manuel Congo, a large collective escape of enslaved people. With worn-out soil and abolition, it fell into decline.", ev: ['coffee', 'eusebio', 'abolition'] },
  'city:Petrópolis': { txt: "Founded in 1843 by decree of Emperor Pedro II in the mountains of Rio de Janeiro, and first settled by German immigrants. It was the summer residence of the emperor and the court. The 1903 treaty with Bolivia that brought Acre into Brazil was signed there.", ev: ['petropolis'] },
  'city:Tokyo': { txt: "The new name of Edo, which became the capital of imperial Japan in 1868 with the Meiji Restoration. From there the government modernized the country in a few decades and, to ease pressure in the countryside, encouraged emigration, including to Brazil from 1908. It was devastated by the earthquake of 1923 and by the bombing of 1945.", ev: ['meiji', 'kasato'] },
  'city:Genoa': { txt: "A former merchant republic in northern Italy, rival of Venice in the Mediterranean. In the late 19th and early 20th centuries, its port shipped hundreds of thousands of Italian emigrants to Argentina and Brazil, especially to the coffee estates of São Paulo.", ev: ['italy', 'immigration'] },
  'city:Naples': { txt: "Former capital of the Kingdom of the Two Sicilies, annexed to unified Italy in 1861. With the poverty of southern Italy after unification, it became one of the great ports of emigration to the Americas, including Brazil.", ev: ['italy', 'immigration'] },
  'city:Rome': { txt: "In 117 AD, under Trajan, it was the capital of an empire stretching from the Atlantic to the Persian Gulf, with perhaps a million inhabitants, fed by wheat from Egypt and Africa. Later it was the seat of the papacy and, in 1871, the capital of unified Italy. Each period on the map shows a different city with the same name.", ev: ['romanrepublic', 'fallofrome', 'italy'] },
  'city:Berlin': { txt: "Capital of Prussia and, from 1871, of the German Empire. There Napoleon decreed the Continental Blockade (1806), and the European powers divided Africa at the Conference of 1884-1885. In the 20th century it was the capital of the Nazi regime and, from 1961 to 1989, it was divided by a wall, the symbol of the Cold War.", ev: ['blockade', 'berlin1884', 'ww2', 'berlinwallfall'] },
  'city:Kobe': { txt: "A Japanese port opened to foreign trade in 1868. In 1908 the Kasato Maru left from there with the first Japanese immigrants to Brazil, and Kobe remained the main port of Japanese emigration to South America.", ev: ['kasato', 'meiji'] },
  'city:Jundiaí': { txt: "A 17th-century town in São Paulo, on the road between São Paulo and the interior. In 1867 it became the end of the line of the São Paulo Railway, which ran down the coastal range to Santos, and from there the coffee railways set out for western São Paulo.", ev: ['coffee', 'immigration'] },
  'city:Campinas': { txt: "It began as a stopping place for muleteers and became, in the 19th century, one of the largest centers of sugar and later of coffee in São Paulo, with many enslaved people. Railways such as the Companhia Paulista (1872) and the Agronomic Institute (1887) started there. After abolition, it received many Italian immigrants.", ev: ['coffee', 'immigration', 'abolition'] },
  'city:Juiz de Fora': { txt: "A city in the Zona da Mata of Minas Gerais, on the Caminho Novo, the road that linked the mines to Rio. With coffee and the União e Indústria road (1861), it received German immigrants and became a textile hub, called the Manchester of Minas. On 31 March 1964, troops left from there for Rio, starting the coup.", ev: ['coffee', 'coup64'] },
  'city:Corumbá': { txt: "Founded in 1778 as Albuquerque, on the banks of the Paraguay River, in the Pantanal, on the border with Bolivia. It was occupied by the Paraguayans from 1865 to 1867. As a river port, it linked Mato Grosso to the Plata and, by river, to the rest of Brazil, before the railways arrived.", ev: ['paraguaywar', 'rondon'] },
  'city:Ribeirão Preto': { txt: "A city in northeastern São Paulo that grew in the late 19th century on the terra roxa, a red soil excellent for coffee. With the Mogiana railway and many Italian immigrants, it became one of the coffee capitals of the Old Republic. After 1929 it diversified into sugarcane and industry.", ev: ['coffee', 'immigration'] },
  'city:Curitiba': { txt: "A town founded in the late 17th century on the plateau, on the route of the muleteers who drove cattle from the South to the mines. It became capital of the province of Paraná in 1853 and received German, Polish, Ukrainian and Italian immigrants.", ev: ['immigration'] },
  'city:Rio Branco': { txt: "It was born from the Empresa rubber estate, on the banks of the Acre River, in a region settled by rubber tappers from the Northeast on land that Bolivia claimed. After the Treaty of Petrópolis (1903), it became the seat of the Territory of Acre. The name honors the Baron of Rio Branco, who negotiated the treaty.", ev: ['petropolis', 'rubber'] },
  'city:Belo Horizonte': { txt: "The planned capital of Minas Gerais, designed by Aarão Reis and inaugurated in 1897 to replace Ouro Preto. Its grid layout with diagonal avenues was meant to symbolize republican order. In the 20th century it became one of the country’s great industrial centers.", ev: ['republic'] },
  'city:Florianópolis': { txt: "The name given to Desterro in 1894, in honor of Floriano Peixoto, after the violent crushing of the Federalist rebels on the island. It is the capital of Santa Catarina. The Hercílio Luz bridge, from 1926, linked the island to the mainland." },
  'city:Natal': { txt: "It was born in 1599 beside the Reis Magos Fort, in Potiguara land. In the Second World War, the United States used the Parnamirim base as an air bridge to Africa, since it was the point in the Americas closest to the other side of the Atlantic.", ev: ['ww2'] },
  'city:Porto Velho': { txt: "It was born around 1907 as the work camp of the Madeira-Mamoré railway, promised to Bolivia in the Treaty of Petrópolis and built at the cost of thousands of lives. The railway was finished in 1912, when rubber was already in crisis. The town became the capital of the Territory of Guaporé, later Rondônia.", ev: ['petropolis', 'rubber', 'rondon'] },
  'city:Guajará-Mirim': { txt: "The end of the line of the Madeira-Mamoré railway, on the Mamoré River, across from the Bolivian town of Guayaramerín. Bolivian rubber was supposed to come down this way to the Amazon, bypassing the rapids of the Madeira.", ev: ['petropolis', 'rubber'] },
  'city:Bauru': { txt: "A town in western São Paulo from which, in 1905, the Noroeste do Brasil railway set out toward Mato Grosso. The works advanced onto Kaingang lands, and the conflict led to the creation of the SPI, the Indian Protection Service, which carried out the so-called pacification in 1912. With the railway, the region became coffee country.", ev: ['rondon', 'coffee'] },
  'city:Campo Grande': { txt: "A settlement of cattle ranchers in southern Mato Grosso, founded in the late 19th century by people from Minas Gerais. The arrival of the Noroeste do Brasil railway in 1914 made it the main center of the region. In 1977 it became the capital of the new state of Mato Grosso do Sul." },
  'city:Brasília': { txt: "A capital planned by Lúcio Costa and Oscar Niemeyer and inaugurated in 1960 by Juscelino Kubitschek, on the central plateau. It was built by migrants from all over the country, the candangos, many of whom ended up living in satellite towns far from the center. Seat of the dictatorship from 1964 and of the Constituent Assembly of 1987-1988.", ev: ['brasilia', 'coup64', 'constitution'] },
  'city:Goiânia': { txt: "The planned capital of Goiás, founded in 1933 by Pedro Ludovico and officially capital in 1937, part of Vargas’s March to the West. It grew fast with the building of Brasília and the spread of farming in the cerrado. In 1987 it suffered the radiological accident with caesium-137.", ev: ['estadonovo', 'brasilia'] },
  'city:Londrina': { txt: "Founded in 1929-1934 by the Companhia de Terras Norte do Paraná, a British-backed company that divided the forest into lots for small and medium coffee farmers. It drew migrants from São Paulo, Minas Gerais and the Northeast, as well as Japanese and Europeans. The region’s forest was almost entirely cut down within a few decades.", ev: ['coffee'] },
  'city:Volta Redonda': { txt: "A town in the Paraíba valley of Rio de Janeiro chosen for the National Steel Company (CSN), built in 1941-1946 with American financing that Vargas negotiated in exchange for Brazil’s support in the Second World War. It was the great symbol of state-led industrialization. In 1988, a strike at the plant ended with three workers killed by the Army.", ev: ['estadonovo', 'ww2'] },
  'city:Teresina': { txt: "Capital of Piauí, planned and founded in 1852 between the Parnaíba and Poti rivers to replace the old, more isolated capital, Oeiras. The name honors Empress Teresa Cristina. It grew as the trading center of the sertão (backlands) of the Mid-North." },
  'city:Imperatriz': { txt: "A city on the banks of the Tocantins River, in western Maranhão, founded in 1852. It grew suddenly with the Belém-Brasília highway in the 1960s and became a hub of the farming and logging frontier, with many land conflicts.", ev: ['brasilia', 'transamazon'] },
  'city:Posto Leonardo (Xingu)': { txt: "A post of the Xingu Indigenous Park, created in 1961, named after Leonardo Villas-Bôas. Together with his brothers Orlando and Cláudio, the Villas-Bôas defended a territory where several peoples could live with relative autonomy. The post offered health care and was a meeting point between the peoples of the park and the state.", ev: ['xingu1961', 'xingu'] },
  'city:Marabá': { txt: "A city in southeastern Pará, where the Tocantins and Itacaiúnas rivers meet, which lived on Brazil nuts. In the 1970s and 1980s it was the center of a violent frontier: the Araguaia guerrilla and its repression, the Trans-Amazonian Highway, the Serra Pelada gold rush and the Carajás mines. Land conflicts in the region are among the most violent in the country.", ev: ['transamazon', 'coup64'] },
  'city:Altamira': { txt: "A city on the Xingu River, in Pará, chosen by the military government in 1970 for the launch of the Trans-Amazonian Highway. In 1989 it hosted the Gathering of the Indigenous Peoples of the Xingu, led by the Kayapó, against the building of dams. The Belo Monte dam was eventually built there in the 2010s.", ev: ['transamazon'] },
  'city:Itaituba': { txt: "A city on the Tapajós River, in Pará, crossed by the Trans-Amazonian Highway. In the 1970s and 1980s it became the center of gold prospecting in the Tapajós valley, with clandestine airstrips, rivers poisoned by mercury and conflicts with peoples such as the Munduruku.", ev: ['transamazon'] },

  // ---------- 117 AD ----------
  'city:Alexandria': { txt: "Founded by Alexander in 331 BC in the Nile delta, it was the capital of the Ptolemies and, under Rome, the second-largest city of the empire. It had the lighthouse and the great library, and its port shipped Egyptian wheat to Rome and received goods from the Red Sea and India.", ev: ['alexander', 'romanrepublic'] },
  'city:Antioch': { txt: "Founded around 300 BC by Seleucus, one of Alexander’s generals, in northern Syria, it was one of the largest cities of the Roman East. It was a meeting point of routes to Mesopotamia and one of the first centers of Christianity. Trajan stayed there during the war against the Parthians.", ev: ['alexander'] },
  'city:Carthage': { txt: "Founded by the Phoenicians in present-day Tunisia, it rivaled Rome for the Mediterranean until it was destroyed in 146 BC. Refounded as a Roman colony, it again became one of the largest cities of the West, capital of the province of Africa, which exported wheat and olive oil.", ev: ['romanrepublic'] },
  'city:Athens': { txt: "A Greek city where direct democracy was tried from 508 BC, though only for free men. In 117 AD it was a city of the Roman Empire with little political power, but still the main center of philosophy and learning, admired by the emperor Hadrian.", ev: ['athens'] },
  'city:Byzantium': { txt: "A Greek colony on the Bosporus strait, between Europe and Asia, controlling the passage to the Black Sea. In 117 it was a medium-sized city of the Roman Empire. In 330, Constantine refounded it as Constantinople, capital of the Eastern Roman Empire.", ev: ['constantinople1453'] },
  'city:Ephesus': { txt: "A Greek city on the coast of Asia Minor, capital of the Roman province of Asia and one of the largest in the empire. It had the Temple of Artemis, one of the seven wonders of the ancient world, and the apostle Paul preached there. The silting of its harbor led to its decline.", ev: ['romanrepublic'] },
  'city:Lugdunum': { txt: "Present-day Lyon, in France, founded by the Romans in 43 BC where the Rhône and Saône rivers meet. It was the main city of Roman Gaul, with a mint and the altar where the Gallic tribes gathered for the cult of the emperor.", ev: ['romanrepublic'] },
  'city:Londinium': { txt: "Present-day London, founded by the Romans around 47 AD at a point on the Thames that was easy to cross. It was burned in Boudica’s revolt in 60-61 and rebuilt as the main port and trading center of Roman Britain. It was abandoned in the 5th century, after Rome withdrew.", ev: ['fallofrome'] },
  'city:Colonia': { txt: "Colonia Agrippina, present-day Cologne, in Germany, a Roman city on the Rhine, on the frontier with the Germanic peoples. It was the capital of the province of Lower Germany and a base for troops and for trade across the river.", ev: ['fallofrome'] },
  'city:Tarraco': { txt: "Present-day Tarragona, on the coast of Catalonia, one of the first Roman bases in the Iberian Peninsula, from 218 BC. It was the capital of the province of Tarraconensis, the largest in Roman Hispania.", ev: ['romanrepublic'] },
  'city:Gades': { txt: "Present-day Cádiz, founded by the Phoenicians around 1100 BC, according to tradition, on an island near the Strait of Gibraltar, one of the oldest cities of the West. Under Rome, it exported salted fish and garum sauce. Centuries later, as Cádiz, it inherited from Seville the monopoly of trade with the Americas.", ev: ['romanrepublic'] },
  'city:Leptis Magna': { txt: "A city of Phoenician origin on the coast of present-day Libya, made rich by olive oil. It was the birthplace of Septimius Severus, emperor from 193 to 211, who filled it with monuments. Its ruins are among the best preserved in the Roman world.", ev: ['romanrepublic'] },
  'city:Jerusalem': { txt: "A city sacred to Jews and later to Christians and Muslims. The Romans destroyed the Temple in 70 AD, after a great Jewish revolt. After another revolt, in 132-135, Hadrian refounded the city as a Roman colony, Aelia Capitolina, and banned Jews from living there.", ev: ['romanrepublic'] },
  'city:Palmyra': { txt: "An oasis city in the Syrian desert, made rich by the caravans that carried goods from the Persian Gulf and India to the Mediterranean. It was part of the Roman Empire, but with a great deal of autonomy. In the 3rd century, Queen Zenobia went so far as to challenge Rome.", ev: ['hansilkroad'] },
  'city:Ctesiphon': { txt: "Capital of the Parthian Empire on the banks of the Tigris, in Mesopotamia, and later of the Sasanians. Trajan took it in 116, but Rome gave up the conquest soon after. Baghdad was founded nearby in 762.", ev: ['baghdad'] },
  'city:Merv': { txt: "A great oasis in present-day Turkmenistan, a necessary stop on the Silk Road between Iran and Central Asia. In 117 it was an important city of the Parthian Empire. It was destroyed by the Mongols in 1221.", ev: ['hansilkroad', 'mongols'] },
  'city:Bactra': { txt: "Present-day Balkh, in northern Afghanistan, called the mother of cities. It was conquered by Alexander and later ruled by Greco-Bactrian kings and by the Kushans. It was a crossroads of routes between Persia, India and China and a center of Buddhism.", ev: ['alexander', 'hansilkroad'] },
  'city:Purushapura': { txt: "Present-day Peshawar, in Pakistan, capital of the Kushan Empire under Kanishka, in the 2nd century. It was a Buddhist center in the Gandhara region, where art mixed Greek and Indian styles. It controlled the passage between Central Asia and the Ganges plain.", ev: ['hansilkroad'] },
  'city:Mathura': { txt: "A city on the banks of the Yamuna River, in northern India, one of the centers of the Kushan Empire. It was a religious center for Buddhists, Jains and Hindus, and its workshops produced some of the first images of the Buddha in human form." },
  'city:Pataliputra': { txt: "Present-day Patna, on the Ganges, it was the capital of Ashoka’s Maurya Empire in the 3rd century BC and one of the largest cities in the world at the time. By 117 AD it had lost some of its importance, but it was still a great center of the Ganges valley." },
  'city:Kashgar': { txt: "An oasis city at the far western end of the Tarim basin, in present-day Xinjiang, China, where the silk routes came together before crossing the mountains into Central Asia. The Han fought other steppe peoples for control of it.", ev: ['hansilkroad'] },
  'city:Dunhuang': { txt: "A Han outpost at the end of the Gansu corridor, where the desert begins, and the gateway of the Silk Road into China. Later, the Mogao caves, full of Buddhist paintings, held thousands of manuscripts in many languages, a sign of how many peoples passed through.", ev: ['hansilkroad'] },
  "city:Chang'an": { txt: "Present-day Xi’an, it was the capital of the Western Han and the starting point of the Silk Road. In 117 the capital was at Luoyang, but Chang’an remained a great city. Under the Tang, from 618, it was capital again and one of the largest cities in the world.", ev: ['hansilkroad', 'tangchangan'] },
  'city:Luoyang': { txt: "Capital of the Eastern Han dynasty from 25 AD, on the banks of the Luo River, in central China. The imperial university was there, and the first Buddhist monks from India and Central Asia arrived there. It was sacked in 190, in the collapse of the Han.", ev: ['hansilkroad'] },
  'city:Axum': { txt: "Capital of a kingdom on the plateau of present-day Ethiopia and Eritrea, which flourished from the 1st to the 7th century. It traded ivory and gold across the Red Sea with Rome and India, minted its own coins and adopted Christianity in the 4th century. It is known for its great stone obelisks." },
  'city:Adulis': { txt: "The Red Sea port of Axum, in present-day Eritrea, mentioned in the Periplus of the Erythraean Sea, a 1st-century Greek sailing guide. Ivory, tortoiseshell and goods from India and the Mediterranean passed through it." },
  'city:Barygaza': { txt: "Present-day Bharuch, in Gujarat, western India, one of the great ports of the trade between India and the Roman world. According to the Periplus of the Erythraean Sea, it exported cotton cloth, gems and spices and received wine and Roman coins." },
  'city:Muziris': { txt: "A port on the Malabar Coast, in southwestern India, from which pepper was shipped to Rome. A 2nd-century papyrus records a cargo of enormous value between Muziris and Alexandria. Its exact location has been lost; excavations at Pattanam, in Kerala, are the best candidate." },
  'city:Teotihuacan': { txt: "A great city in the Valley of Mexico, which flourished roughly between 100 BC and 550 AD and reached perhaps 100,000 inhabitants. Most people lived in good-quality apartment compounds, which has led some archaeologists to speak of a housing program for everyone. Its influence reached the Maya cities, such as Tikal.", ev: ['teotihuacan', 'maya'] },

  // ---------- 1279 ----------
  'city:Khanbaliq': { txt: "The city of the khan, present-day Beijing, built by Kublai Khan from 1267 as the capital of the Yuan dynasty. In 1279 the Mongols completed the conquest of China. Marco Polo described the city, linked by canals and post stations to the whole empire.", ev: ['mongols'] },
  'city:Sarai': { txt: "Capital of the Golden Horde, on the banks of the lower Volga, founded by Batu in the 1240s. From there the Mongol khans collected tribute from the Russian principalities. It was a market on routes running from Central Asia to the Black Sea.", ev: ['mongols', 'blackdeath'] },
  'city:Tabriz': { txt: "Capital of the Ilkhanate, the Mongol khanate of Iran, in the northwest of present-day Iran. It was a center of trade between Asia, the Mediterranean and the Indian Ocean, visited by Italian merchants. There the vizier Rashid al-Din wrote one of the first histories of the whole world.", ev: ['mongols'] },
  'city:Almalik': { txt: "Capital of the Chagatai Khanate, in Central Asia, near the present-day border between China and Kazakhstan. It was a stop on the silk routes under Mongol rule. It disappeared in the 14th century, and today few ruins remain.", ev: ['mongols'] },
  'city:Cairo': { txt: "Founded in 969 by the Fatimids near older settlements, in 1279 it was the capital of the Mamluks, who had stopped the Mongols at Ain Jalut in 1260. It was one of the largest cities in the world and a center of trade between the Indian Ocean and the Mediterranean. Mansa Musa of Mali passed through in 1324 and spent so much gold that its price fell.", ev: ['mongols', 'mansamusa'] },
  'city:Delhi': { txt: "Capital of the Delhi Sultanate, founded in 1206 by generals of Turkic origin. It resisted the Mongol invasions and took in refugees from all over Central Asia. Centuries later it was the capital of the Mughal Empire, and today it is the seat of India’s government.", ev: ['mongols', 'india1947'] },
  'city:Aachen': { txt: "A city in the west of present-day Germany, the favorite residence of Charlemagne, crowned emperor in 800. For centuries, German kings were crowned in its chapel. In 1279, the Holy Roman Empire was a patchwork of principalities with little central power." },
  'city:Constantinople': { txt: "Capital of the Byzantine Empire, Rome’s heir in the East, retaken in 1261 after more than half a century in the hands of the Latin crusaders. It controlled the strait between the Black Sea and the Mediterranean, although trade was more and more in the hands of the Genoese and Venetians. It was taken by the Ottomans in 1453.", ev: ['constantinople1453'] },
  'city:Niani': { txt: "A town in present-day Guinea, traditionally held to be the capital of the Mali Empire, which controlled gold and the routes across the Sahara. The location of the capital is debated: digs at Niani found no strong traces of the 14th century, and some historians think the court moved around. Mali reached its peak under Mansa Musa, in the 14th century.", ev: ['mansamusa'] },
  'city:Hangzhou': { txt: "Capital of the Southern Song, called Lin’an, and perhaps the largest city in the world in the 13th century, with canals, markets and paper money. The Mongols took it in 1276. Marco Polo described it in amazement as Quinsai.", ev: ['mongols'] },
  'city:Venice': { txt: "A merchant republic built on islands in a lagoon of the Adriatic, which grew powerful on trade between Europe and the East. Its merchants, such as the Polo family, traveled as far as Mongol China. Italian galleys carried the Black Death from the Black Sea to Europe in 1347.", ev: ['blackdeath', 'mongols'] },

  // ---------- 1914 ----------
  'city:Saint Petersburg': { txt: "Founded by Peter the Great in 1703 to be the capital of the Russian Empire and its window on Europe. In 1914 it was renamed Petrograd, to sound less German. The revolutions of 1917 began there.", ev: ['russianrev1917'] },
  'city:Istanbul': { txt: "Formerly Constantinople, capital of the Ottoman Empire since 1453. In 1914 the empire, already much reduced, entered the First World War on Germany’s side. After the defeat it was broken up, and the capital of the new Turkey moved to Ankara in 1923.", ev: ['constantinople1453', 'ww1'] },
  'city:Washington': { txt: "The planned capital of the United States, seat of government since 1800. By 1914 the country was already the largest industrial economy in the world and a major buyer of Brazil’s coffee and rubber. After 1945, it was one of the two poles of the Cold War.", ev: ['usa', 'coldwar'] },
  'city:Vienna': { txt: "Capital of the Austro-Hungarian Empire, which brought together many peoples and languages in central Europe. The Congress of Vienna of 1815, which reorganized Europe after Napoleon, met there. The murder of the heir to the throne in Sarajevo, in 1914, led the empire into war.", ev: ['vienna', 'ww1'] },
  'city:The Hague': { txt: "Seat of the government of the Netherlands and of the Peace Conferences of 1899 and 1907, which tried to set rules for war and for arbitration between countries. At the 1907 conference, Rui Barbosa defended equality between large and small states. Today it is home to the International Court of Justice." },
  'city:Bombay': { txt: "Present-day Mumbai, islands handed by Portugal to England in 1661 as the dowry of Catherine of Braganza. Under British rule it became India’s largest port and textile center, exporting cotton. It was also one of the centers of the independence movement.", ev: ['saltmarch', 'india1947'] },
  'city:Shanghai': { txt: "A port at the mouth of the Yangtze forced open to foreign trade after the Opium War, in 1842. It had concessions controlled by the British, French and others, and it became the largest industrial and financial center in China. It was one of the stages of the struggles that ended in the revolution of 1949.", ev: ['opium', 'china1949'] },
  'city:Cape Town': { txt: "Founded in 1652 by the Dutch East India Company as a stop on the way to Asia, on Khoikhoi land. It passed to the British in the early 19th century. It was one of the centers of the regime of racial segregation that ended in the 1990s, when Nelson Mandela came out of prison and spoke in the city.", ev: ['vocamsterdam', 'apartheid'] },

  // ---------- Regions and peoples ----------
  'reg:cerrado hunters': { txt: "Groups of hunter-gatherers who, from about 12,000 years ago, lived in central Brazil, in rock shelters in Goiás, Minas and Bahia. Archaeologists link them to the Itaparica tradition, with very finely made chipped-stone scrapers, and to sites such as Lagoa Santa, where Luzia lived. They hunted small and medium animals and gathered many fruits and roots, not just megafauna.", ev: ['luzia'] },
  'reg:forest peoples': { txt: "The first inhabitants of the Amazon, who were already there some 11,000 years ago, as the Caverna da Pedra Pintada at Monte Alegre shows. They lived by fishing, hunting and gathering palm fruits and nuts. They began early to manage the forest, favoring the useful plants that are still concentrated near ancient sites today.", ev: ['pedrapintada', 'terrapreta'] },
  'reg:Andean hunters': { txt: "Groups who settled the Andean highlands more than 12,000 years ago, hunting guanacos and vicuñas and living in caves such as Guitarrero and Lauricocha, in Peru. Little by little they domesticated the llama, the alpaca, the potato and quinoa. On that base, thousands of years later, cities such as Caral and Tiwanaku arose." },
  'reg:pampas hunters': { txt: "Hunters who lived on the plains of Uruguay, Argentina and southern Brazil at the end of the ice age. At sites such as Arroyo Seco 2, in Argentina, there are bones of megafauna, such as giant sloths and native horses, alongside stone tools. They used fishtail-shaped stone points, common throughout the Southern Cone." },
  'reg:sambaqui peoples': { txt: "Fishing and foraging peoples who, for thousands of years, lived on the coast of Brazil, from Espírito Santo to Rio Grande do Sul, and built the sambaquis (shell mounds). They lived in one place, buried their dead with care and exchanged objects along the coast. Around a thousand years ago they were replaced or absorbed by pottery-making peoples, such as the southern Jê and later the Tupi.", ev: ['sambaquis'] },
  'reg:first gardens': { txt: "In southwestern Amazonia and other areas, foraging peoples began some 8,000 to 10,000 years ago to grow manioc, squash, peanuts and chili peppers. Amazonia is now seen as one of the world’s independent centers of plant domestication. For thousands of years these gardens coexisted with hunting, fishing and gathering, with no leap to full-time farming.", ev: ['terrapreta', 'balsasmaize'] },
  'reg:expanding Tupi-Guarani peoples': { txt: "Peoples speaking Tupi-Guarani languages who, starting from southwestern Amazonia, spread in great movements along the coast and through the Plata basin during the first millennium AD. They brought manioc and maize gardens and painted pottery. The exact routes and dates of the expansion are still debated.", ev: ['tupiguarani'] },
  'reg:Jê peoples': { txt: "Peoples speaking Jê languages, from the central plateau and the south of Brazil, such as the ancestors of the Kayapó, Xavante, Timbira and Kaingang. Many lived in large circular villages, with houses around a plaza and a social life divided into halves. In the south, they built pit houses to protect themselves from the cold of the plateau." },
  'reg:Arawak and Carib peoples': { txt: "Two great language families of the Amazon and the Caribbean. Arawak peoples spread along rivers from the Orinoco to Bolivia, with large villages, long-distance trade and dark earth; Carib peoples lived mainly in the northern Amazon and the Guianas. Both took part in regional systems with other peoples, as in the upper Xingu and perhaps on Marajó.", ev: ['marajoara', 'xingu'] },
  'reg:Tupi peoples': { txt: "The coastal Tupi peoples, such as the Tupinambá, Tupiniquim, Potiguara and Caeté, held almost the whole coast when the Europeans arrived. They lived in villages of longhouses, with manioc gardens, chiefs who persuaded rather than commanded, and ritual wars between villages. They were the first partners, allies and victims of the Portuguese and French.", ev: ['tupi', 'tupiguarani', 'brazilwood', 'tamoios'] },
  'reg:Guarani peoples': { txt: "The Guarani held the forests of the Plata basin, from the coast of Santa Catarina to Paraguay, in villages with gardens of maize and manioc. They spoke a language very close to that of the coastal Tupi. They were allies of the Spaniards of Asunción, gathered by the Jesuits into missions and hunted by the bandeirantes.", ev: ['missions', 'bandeiras', 'guaraniwar'] },
  'reg:upper Xingu': { txt: "The region of the headwaters of the Xingu River, where peoples speaking Arawak, Carib and Tupi languages formed a regional system of exchange, marriage and ceremonies such as the Kuarup. Between about 1250 and 1600, there were large villages there linked by roads. The region stayed out of colonial reach until the 20th century.", ev: ['xingu', 'xingu1961'] },
  'reg:Jê peoples and "Tapuias"': { txt: "Tapuia was the generic name that the Portuguese and the Tupi gave to the peoples of the interior who did not speak Tupi, mostly speakers of Jê or other language families. The chroniclers described them as barbarians, but they were very diverse peoples, such as the Kariri, Aimoré and Tarairiú. They resisted the spread of cattle ranching in the sertão, above all in the so-called War of the Barbarians (c. 1650-1720)." },
  'reg:Amazonia: hundreds of peoples': { txt: "Hundreds of peoples from dozens of language families lived, and still live, in Amazonia. Epidemics, missions, enslavement and later rubber greatly reduced this population, but much of the forest remained under Indigenous control until the 20th century. The Amazonian population of 1500 is much debated: estimates range from a few million to far more.", ev: ['terrapreta', 'cabanagem', 'rubber'] },
  'reg:Ndongo': { txt: "A kingdom of the Mbundu in the interior of present-day Angola, ruled by a king called the ngola, which gave Angola its name. The Portuguese of Luanda waged war on it from the late 16th century, seeking people for the slave trade. Queen Nzinga Mbande (ruled from about 1624 to 1663) resisted for decades, sometimes at war, sometimes in alliance with the Dutch.", ev: ['luanda', 'luanda1641', 'slavetrade'] },
  'reg:Jê peoples of central Brazil': { txt: "Jê-speaking peoples of the central plateau, such as the Kayapó, Xavante, Xerente, Akroá and Xakriabá. With the gold rush in Minas, Goiás and Mato Grosso, they were attacked by bandeiras and settlers, and some were gathered into mission villages (aldeamentos). Many withdrew westward and resisted until the 20th century.", ev: ['gold'] },
  'reg:Payaguá and Guaikuru': { txt: "The Payaguá, canoe people of the Paraguay River, and the Guaikuru, or Mbayá, horsemen of the Chaco and the Pantanal, were the great enemies of the São Paulo monções, the canoe convoys bound for Cuiabá. The Guaikuru adopted the horse brought by the Spaniards and dominated neighboring farming peoples. The Kadiwéu of Mato Grosso do Sul are descendants of the Mbayá.", ev: ['gold'] },
  'reg:Charrúa and Minuano': { txt: "Peoples of the pampas, between present-day Uruguay, Rio Grande do Sul and the Argentine coast, who adopted the horse and the free-roaming cattle (gado chimarrão) brought by the Europeans. They were allies or enemies of the Portuguese and Spaniards depending on the moment. The massacre of Salsipuedes (1831), in Uruguay, marks the destruction of the last independent Charrúa groups.", ev: ['madrid', 'cisplatina'] },
  'reg:Botocudos (Borum)': { txt: "Botocudo was the name the Portuguese gave to peoples of the Doce River valley, between Minas, Espírito Santo and Bahia, because of the wooden plugs (botoques) in their lips and ears; they called themselves Borum. In 1808, soon after arriving in Rio, Prince Regent João declared a \"just war\" against them, allowing their enslavement and the seizure of their lands. The Krenak are their present-day descendants.", ev: ['court'] },
  'reg:Mapuche and Tehuelche': { txt: "The Mapuche, of southern Chile and Argentina, resisted the Incas and the Spaniards, and for centuries they negotiated with the Crown as an independent people. The Tehuelche were hunters of Patagonia. Between 1861 and 1885, Chile and Argentina conquered their lands by force in the so-called Pacification of Araucanía and Conquest of the Desert." },
  'reg:Kaingang': { txt: "A Jê-speaking people of the southern plateau and western São Paulo, descended from the builders of pit houses. In the 19th and early 20th centuries, their lands were taken by coffee estates, immigrant settlers and railways, with many massacres. In 1912, the SPI carried out the so-called pacification of the Kaingang of western São Paulo.", ev: ['rondon', 'immigration'] },
  'reg:Qom and Wichí (Chaco)': { txt: "Peoples of the Gran Chaco, the dry, wooded plain between Argentina, Paraguay and Bolivia. They kept their autonomy until the late 19th century, when Argentine military campaigns occupied the region and pushed them into work on the sugar plantations and in cotton. In 1924, the Napalpí massacre killed hundreds of Qom and Mocoví." },
  'reg:rubber estates': { txt: "Forest areas where latex was tapped from rubber trees, mainly in Acre, Amazonas and Pará, between 1879 and 1912. The rubber tappers, many of them people from the Northeast fleeing drought, worked bound by debts to their boss, in the aviamento system of credit and supply. The spread of the rubber estates invaded the lands of many Indigenous peoples and led to the dispute over Acre with Bolivia.", ev: ['rubber', 'petropolis'] },
  'reg:sertão': { txt: "The semi-arid interior of the Northeast, a land of caatinga scrub and cattle ranching, where periodic droughts drove people away. In the Old Republic it was the land of coronéis (local strongmen), cangaceiros (bandits) and religious movements such as Canudos, destroyed by the Army in 1897. Euclides da Cunha wrote Os Sertões (Rebellion in the Backlands) about that war.", ev: ['canudos'] },
  'reg:Nambikwara and Paresi': { txt: "Peoples of northwestern Mato Grosso and Rondônia, whose lands the telegraph line of the Rondon Commission (1907-1915) crossed. The Paresi, who already had contact with the colonizers, worked on the line; the Nambikwara resisted and were later decimated by disease. Claude Lévi-Strauss visited them in 1938 and wrote about them in Tristes Tropiques.", ev: ['rondon'] },
  'reg:Xavante': { txt: "A Jê-speaking people of eastern Mato Grosso, who withdrew to the Serra do Roncador and avoided contact until the 1940s. Vargas’s March to the West and the Roncador-Xingu expedition reached their lands, and the government publicized the peaceful contact of 1946. Later, ranches advanced onto the territory, which the Xavante partly won back.", ev: ['estadonovo', 'brasilia'] },
  'reg:Kayapó': { txt: "The Mebêngôkre, a Jê-speaking people, live in southern Pará and northern Mato Grosso, in large circular villages. They faced gold miners, loggers and roads such as the Trans-Amazonian Highway and, in the 1980s, became leading actors in Indigenous politics, pressing the Constituent Assembly and organizing the Altamira Gathering of 1989. Raoni became known around the world.", ev: ['transamazon', 'constitution'] },
  'reg:Yanomami': { txt: "A forest people of the border between Brazil and Venezuela, in Roraima and Amazonas, who live in large communal houses. The Perimetral Norte highway in the 1970s, and the invasion of tens of thousands of gold miners in the late 1980s, brought disease and death. Yanomami land was demarcated in 1992, under the leadership of Davi Kopenawa.", ev: ['constitution'] },
  'reg:Tikuna': { txt: "A people of the upper Solimões, on the border with Peru and Colombia, today the most numerous Indigenous people in Brazil. For a long time they worked for rubber bosses, and only from the 1980s did they have lands demarcated. In 1988, the Capacete massacre killed Tikuna who had gathered to wait for the authorities.", ev: ['constitution'] },
  'reg:Guarani': { txt: "Today’s Guarani, such as the Kaiowá, Ñandeva and Mbya, live in Mato Grosso do Sul, in the South and on the coast of the Southeast. In the 20th century, the SPI confined them to small reserves while ranches took over their lands. From the 1980s, the Kaiowá began to retake old territories, in conflicts that continue; the leader Marçal de Souza was murdered in 1983.", ev: ['rondon', 'constitution'] },
  'reg:agricultural frontier': { txt: "The advance of cattle ranches, soy and colonization onto the cerrado and the Amazon from the 1970s, encouraged by the dictatorship with roads, credit and projects such as the Trans-Amazonian Highway and the BR-364 in Rondônia. It brought large-scale deforestation and conflicts with Indigenous peoples, squatters and rubber tappers. Chico Mendes, a rubber tappers’ leader from Acre, was killed in 1988.", ev: ['transamazon', 'coup64', 'constitution'] }
};
